 "content": "def transform(grid):
    """Replicate the non-separator stencil across each tile row, recolored by its seed."""
    h, w = len(grid), len(grid[0])
    # Separator lines are uniform and occur in both dimensions.
    row_lines = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    if not row_lines or not col_lines:
        return [row[:] for row in grid]
    sep = grid[row_lines[0]][0]
    row_lines = [r for r in row_lines if grid[r][0] == sep]
    col_lines = [c for c in col_lines if grid[0][c] == sep]
    row_bounds = [-1] + row_lines + [h]
    col_bounds = [-1] + col_lines + [w]
    row_tiles = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_tiles = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]
    out = [row[:] for row in grid]
    # Find a stencil in any tile other than the first (seed) column.
    stencil = None
    for ti, (r0, r1) in enumerate(row_tiles):
        for tj, (c0, c1) in enumerate(col_tiles):
            if tj == 0:
                continue
            cells = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0 and grid[r][c] != sep]
            if cells:
                stencil = (r1-r0, c1-c0, cells)
                break
        if stencil:
            break
    if stencil is None:
        return out
    sh, sw, pattern = stencil
    for r0, r1 in row_tiles:
        # Seed color is the nonzero, non-separator color in the first tile of this row.
        seed_colors = {grid[r][c] for r in range(r0, r1) for c in range(col_tiles[0][0], col_tiles[0][1]) if grid[r][c] not in (0, sep)}
        if not seed_colors:
            continue
        color = min(seed_colors)
        for c0, c1 in col_tiles:
            # Clear tile contents, then stamp the stencil (aligned to the tile's top-left).
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in pattern:
                if dr < r1-r0 and dc < c1-c0:
                    out[r0+dr][c0+dc] = color
    return out
